 const skyMat=new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{topColor:{value:new THREE.Color(timeThemes[0].sky)},bottomColor:{value:new THREE.Color(timeThemes[0].horizon)}},vertexShader:'varying vec3 vDirection; void main(){vDirection=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'varying vec3 vDirection;uniform vec3 topColor;uniform vec3 bottomColor;void main(){float h=normalize(vDirection).y;vec3 c=mix(bottomColor,topColor,pow(max(0.,h),.55));gl_FragColor=vec4(c,1.); #include <tonemapping_fragment>\n #include <colorspace_fragment> }'.replace(' #include','\n#include')});sky=new THREE.Mesh(new THREE.SphereGeometry(2500,24,16),skyMat);sky.frustumCulled=false;scene.add(sky);
